import{_ as i,o as t,c as n,ag as s}from"./chunks/framework.DKalukzk.js";const m=JSON.parse('{"title":"TP4 — Présentation PowerPoint : enjeux du métier en informatique","description":"","frontmatter":{},"headers":[],"relativePath":"travaux/tp4-ppt-ethique.md","filePath":"travaux/tp4-ppt-ethique.md"}'),r={name:"travaux/tp4-ppt-ethique.md"};function o(l,e,a,u,p,c){return t(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="tp4-—-presentation-powerpoint-enjeux-du-metier-en-informatique" tabindex="-1">TP4 — Présentation PowerPoint : enjeux du métier en informatique <a class="header-anchor" href="#tp4-—-presentation-powerpoint-enjeux-du-metier-en-informatique" aria-label="Permalink to &quot;TP4 — Présentation PowerPoint : enjeux du métier en informatique&quot;">​</a></h1><h2 id="objectif" tabindex="-1">Objectif <a class="header-anchor" href="#objectif" aria-label="Permalink to &quot;Objectif&quot;">​</a></h2><p>Réaliser, en équipe, une présentation PowerPoint courte et structurée qui analyse un enjeu réel (éthique, légal ou professionnel) lié au travail en informatique, puis défendre la position de votre équipe à l’oral.</p><h2 id="contexte" tabindex="-1">Contexte <a class="header-anchor" href="#contexte" aria-label="Permalink to &quot;Contexte&quot;">​</a></h2><p>Le métier en informatique implique des choix qui ont des impacts concrets : données personnelles, biais et automatisation, cybersécurité, propriété intellectuelle, conditions de travail, responsabilité professionnelle, conformité, etc.</p><p>Votre rôle : partir d’une situation réaliste (actuelle) et explorer les enjeux, le cadre applicable et les conséquences possibles.</p><blockquote><p>Important : votre présentation doit être basée sur un enjeu réel (actualité, pratique d’entreprise, cas plausible). Évitez les scénarios « science-fiction » ou trop généraux.</p></blockquote><h2 id="travail-a-realiser" tabindex="-1">Travail à réaliser <a class="header-anchor" href="#travail-a-realiser" aria-label="Permalink to &quot;Travail à réaliser&quot;">​</a></h2><ul><li><p>Travail en équipe.</p></li><li><p>Choisir un enjeu réel (éthique / légal / professionnel) lié à l’informatique.</p></li><li><p>Sélection du thème (obligatoire) : <a href="https://livecegepfxgqc-my.sharepoint.com/:x:/g/personal/otremblay_cegepgarneau_ca/IQDbfssXZNCcRYrsZF0e6i4lAQYQRTEEYfGvb0LwHEYL9mM?e=HcWkTX" target="_blank" rel="noreferrer">Thèmes TP4 (choix)</a></p></li><li><p>Produire un diaporama PowerPoint et une présentation orale.</p></li></ul><blockquote><p>Important : choisissez un thème qui n’est pas déjà pris (réservé par une autre équipe).</p></blockquote><p><strong>Structure obligatoire de la présentation</strong></p><ul><li><strong>Problématique</strong><ul><li>Quelle est la situation ? Quel est le problème à résoudre ?</li><li>Qui est concerné (utilisateurs, employeur, public, client, État, etc.) ?</li></ul></li><li><strong>Analyse</strong><ul><li>Faits importants, causes, risques, zones d’incertitude.</li><li>Arguments des différentes parties (au moins 2 points de vue).</li></ul></li><li><strong>Cadre légal / éthique</strong><ul><li>Règles, obligations, bonnes pratiques, codes de conduite (selon le sujet).</li><li>Principes éthiques pertinents (ex. confidentialité, transparence, équité, minimisation des données, responsabilité).</li></ul></li><li><strong>Conséquences</strong><ul><li>Effets possibles si on agit / si on n’agit pas.</li><li>Impacts : humains, organisationnels, financiers, réputationnels, juridiques.</li></ul></li><li><strong>Position de l’équipe</strong><ul><li>Votre recommandation claire. <ul><li>Est-ce qu&#39;il faut faire quelquechose? Nuancez votre point.</li></ul></li><li>Justification (2–4 arguments solides).</li></ul></li></ul><blockquote><p>Important : votre équipe doit prendre position. Une simple description du sujet n’est pas suffisante.</p></blockquote><p><strong>Exemples de sujets (à adapter, pas à copier mot à mot)</strong></p><ul><li>Utilisation d’IA générative au travail : confidentialité, qualité, traçabilité.</li><li>Collecte de données dans une application : consentement, minimisation, conservation.</li><li>Gestion d’une fuite de données : obligations, communication, responsabilités.</li><li>Logiciels piratés / licences : risques légaux et professionnels.</li><li>Sécurité « rapide » vs sécurité « correcte » : pression de livraison, dette technique.</li><li>Plagiat / réutilisation de code : attribution, licences open source, intégrité.</li><li>Accessibilité numérique : obligations, inclusion, qualité.</li><li>Télétravail : sécurité, gestion des appareils, bonnes pratiques.</li></ul><h2 id="contraintes-presentation-orale-et-remise" tabindex="-1">Contraintes, présentation orale et remise <a class="header-anchor" href="#contraintes-presentation-orale-et-remise" aria-label="Permalink to &quot;Contraintes, présentation orale et remise&quot;">​</a></h2><p><strong>Contraintes PowerPoint (obligatoires)</strong></p><ul><li>Lisibilité : typographie simple, taille de police suffisante.</li><li>Peu de texte : phrases courtes, mots-clés.</li><li>Visuels utiles : schémas, pictogrammes, captures, tableaux (si pertinent).</li><li>Cohérence : même style, mêmes repères (titres, couleurs, mise en page).</li></ul><p><strong>Présentation orale</strong></p><ul><li>Durée : courte et maîtrisée (max 10 minutes).</li><li>Tous les membres participent de façon visible.</li><li>Expliquer vos idées : ne pas lire les diapositives.</li></ul><blockquote><p>Important : si un membre ne participe pas à l’oral (absent / ne prend pas du tout la parole), la note de zéro lui sera octroyée.</p></blockquote><p><strong>Remise avant la présentation</strong></p><ul><li>Un fichier <code>.pptx</code>.</li><li><strong>Remis sur Léa avant la présentation de l&#39;équipe</strong>.</li></ul><p><strong>Conseils</strong></p><ul><li>Choisissez un enjeu assez précis pour pouvoir conclure.</li><li>Vérifiez vos sources et gardez une trace (liens, titres, dates).</li><li>Testez la présentation : minutez, simplifiez, améliorez la clarté.</li><li>Utilisez une diapo de conclusion qui résume votre position en 3 points.</li></ul>',25)])])}const q=i(r,[["render",o]]);export{m as __pageData,q as default};
